create table access_method (id uuid not null, user_id uuid not null, provider_name varchar(255) not null, provider_user_id varchar(255) not null, primary key (id), unique (provider_name, provider_user_id));
create table app_user (registration_timestamp timestamp(6) with time zone not null, artist_id uuid, id uuid not null, display_name varchar(20) not null unique, first_name varchar(20), last_name varchar(20), middle_name varchar(20), primary key (id));
create table artist (registration_timestamp timestamp(6) with time zone not null, id uuid not null, name varchar(255) not null, primary key (id));
create table artist_request (req_foundation_date date, timestamp timestamp(6) with time zone not null, id uuid not null, req_artist_id uuid, user_id uuid not null, req_name varchar(255), status varchar(255) not null check ((status in ('PENDING','ACCEPTED','REJECTED'))), primary key (id), constraint ck_exclusive_request_type check ((req_name IS NOT NULL AND req_foundation_date IS NOT NULL AND req_artist_id IS NULL) OR (req_name IS NULL AND req_foundation_date IS NULL AND req_artist_id IS NOT NULL)));
create table outbox_event (retry_count integer not null, created_at timestamp(6) with time zone not null, next_attempt_at timestamp(6) with time zone not null, processing_started_at timestamp(6) with time zone, published_at timestamp(6) with time zone, id uuid not null, aggregate_id varchar(255) not null, event_type varchar(255) not null, last_error varchar(255), status varchar(255) not null check ((status in ('PENDING','PROCESSING','PUBLISHED','FAILED'))), topic varchar(255) not null, payload jsonb not null, primary key (id));
alter table if exists access_method add constraint fk_access_method_user foreign key (user_id) references app_user;
alter table if exists app_user add constraint fk_app_user_artist foreign key (artist_id) references artist;
alter table if exists artist_request add constraint fk_artist_request_artist foreign key (req_artist_id) references artist;
alter table if exists artist_request add constraint fk_artist_request_user foreign key (user_id) references app_user;
